/**
 * The Module Library: browses the entire theBud OS course — 28 OS kernel
 * modules, 18 browser-security modules, ~26 cross-cutting deep-dive lesson
 * clusters, and the prerequisites. Every item shows its real tutorial.html,
 * its real DECISIONS.md deep dive, its real source (with new/modified/
 * carried-over badges across the cumulative kernel), and verified doc
 * links — generated by scripts/generate-library.mjs, never hand-transcribed.
 *
 * The library.generated.ts data file is ~7MB (the full source of a
 * 28-module cumulative kernel, deduplicated), so it's dynamically imported
 * the first time this view opens rather than bundled into the initial page
 * load that the boot simulator needs.
 */
import type {
  LibOsModule,
  LibBrowserModule,
  LibCluster,
  LibPrereqTopic,
  LibFile,
} from './library.generated';

type LibraryData = typeof import('./library.generated');
let DATA: LibraryData | null = null;

/** Overrides every custom property the course's inline tutorial stylesheets
 * define (--bg/--bg2/--bg3/--card/--border/--gold/--cyan/--teal/--red/
 * --green/--purple/--orange/--text/--muted/--code-bg — verified by grepping
 * a real tutorial.html's :root block) with this app's own gold-on-black
 * theme, keeping the semantic callout colors (cyan/teal/purple/orange)
 * intact since those encode meaning, not brand. The three font roles are
 * hardcoded per-selector in the source stylesheets rather than routed
 * through a variable, so they need an explicit, higher-specificity
 * override instead of a variable redefinition. Appended as the LAST
 * <style> in <body>, so it wins the cascade regardless of source order. */
const FONT_IMPORT = `@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700;800&family=JetBrains+Mono:wght@400;500;700&family=Inter:wght@400;500;600&display=swap');`;

const THEME_OVERRIDE_CSS = `
  ${FONT_IMPORT}
  :root {
    --bg:#0b0b0d; --bg2:#141416; --bg3:#18181b; --card:#18181b;
    --border:#2a2a2e; --gold:#d4a017; --gold2:#b8860f; --cyan:#38bdf8; --teal:#2dd4bf;
    --red:#f87171; --green:#4ade80; --purple:#a78bfa; --orange:#fb923c;
    --text:#eeece6; --muted:#9a9992; --code-bg:#101012;
  }
  body, p, li, td, th, dd, dt, .tagline, .qa .a, .qa .q { font-family: 'Inter', -apple-system, sans-serif !important; }
  h1, h2, h3, h4, .hero h1, .hero-stat .num { font-family: 'Space Grotesk', system-ui, sans-serif !important; }
  code, pre, pre code, .cmd .line, .cmd .prompt, .cmd .comment, .module-badge {
    font-family: 'JetBrains Mono', ui-monospace, monospace !important;
  }
`;

/** The 5 custom_lessons_bobos_prerequisites pages were authored from a
 * completely different template than every other page in the course —
 * fingerprinted by `--panel:` in their :root — with its own variable
 * vocabulary (--panel/--line/--blue/--soft/--shadow/--radius instead of
 * --card/--border/--gold/--muted) AND a body background hardcoded as a
 * literal blue-tinted radial-gradient rather than routed through --bg, so
 * redefining variables alone would leave the page visibly blue. Both are
 * covered here: the variables are remapped (--blue/--blue-2, the role
 * this template uses for links/headings/accents, onto this app's gold),
 * and the literal gradients are overridden directly with !important. */
const THEME_OVERRIDE_CSS_ALT = `
  ${FONT_IMPORT}
  :root {
    --bg:#0b0b0d; --panel:#18181b; --panel-2:#141416; --line:#2a2a2e;
    --text:#eeece6; --muted:#9a9992; --soft:#9a9992;
    --blue:#d4a017; --blue-2:#b8860f; --green:#4ade80; --red:#f87171;
    --amber:#d9a441; --purple:#a78bfa; --cyan:#38bdf8; --pink:#f472b6;
  }
  html, body { background: #0b0b0d !important; }
  .hero, .hero::after { background: radial-gradient(circle, rgba(212,160,23,0.16), transparent 65%) !important; }
  body, p, li, td, th, dd, dt { font-family: 'Inter', -apple-system, sans-serif !important; }
  h1, h2, h3, h4 { font-family: 'Space Grotesk', system-ui, sans-serif !important; }
  .formula, .byte, .regbox, .bitfield { font-family: 'JetBrains Mono', ui-monospace, monospace !important; }
`;

/** Wraps a real, full tutorial/concept/lesson HTML document (own <head>,
 * own inline <style>) with the theme override injected right before
 * </body>, so it renders exactly as authored inside a sandboxed iframe —
 * the actual content, restyled to this app's theme instead of the course's
 * native per-page palette. Two source templates exist in this course (see
 * THEME_OVERRIDE_CSS_ALT); which one a page uses is detected from its own
 * :root block rather than tracked per-page in the generated data. */
function buildThemedDoc(html: string): string {
  const override = /--panel\s*:/.test(html) ? THEME_OVERRIDE_CSS_ALT : THEME_OVERRIDE_CSS;
  const styleTag = `<style>${override}</style>`;
  if (/<\/body>/i.test(html)) return html.replace(/<\/body>/i, `${styleTag}</body>`);
  return html + styleTag;
}

function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function escAttr(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}

/** Minimal markdown-lite: paragraphs, "- " lists, numbered lists, fenced
 * code blocks, **bold**, `code`. */
function mdLite(text: string): string {
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const html: string[] = [];
  let buf: string[] = [];
  let mode: 'p' | 'ul' | 'ol' | 'code' | null = null;
  let codeLines: string[] = [];

  const inline = (s: string) =>
    esc(s)
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  function flush() {
    if (mode === 'code') {
      html.push(`<pre><code>${esc(codeLines.join('\n'))}</code></pre>`);
      codeLines = [];
    } else if (buf.length) {
      if (mode === 'ul') html.push('<ul>' + buf.map((l) => `<li>${inline(l)}</li>`).join('') + '</ul>');
      else if (mode === 'ol') html.push('<ol>' + buf.map((l) => `<li>${inline(l)}</li>`).join('') + '</ol>');
      else if (mode === 'p') html.push(`<p>${buf.map(inline).join(' ')}</p>`);
    }
    buf = [];
    mode = null;
  }

  for (const raw of lines) {
    if (/^```/.test(raw.trim())) {
      if (mode === 'code') { flush(); } else { flush(); mode = 'code'; }
      continue;
    }
    if (mode === 'code') { codeLines.push(raw); continue; }
    const line = raw.trim();
    if (!line) { flush(); continue; }
    if (/^(---|\*\*\*)$/.test(line)) { flush(); html.push('<hr>'); continue; }
    if (/^[-*]\s+/.test(line)) {
      if (mode !== 'ul') flush();
      mode = 'ul';
      buf.push(line.replace(/^[-*]\s+/, ''));
    } else if (/^\d+\.\s+/.test(line)) {
      if (mode !== 'ol') flush();
      mode = 'ol';
      buf.push(line.replace(/^\d+\.\s+/, ''));
    } else {
      if (mode !== 'p') flush();
      mode = 'p';
      buf.push(line);
    }
  }
  flush();
  return html.join('\n');
}

type Selection =
  | { kind: 'os'; num: number }
  | { kind: 'browser'; num: number }
  | { kind: 'cluster'; id: string }
  | { kind: 'prereqMain' }
  | { kind: 'prereqTopic'; id: string };

type DetailTab = 'tutorial' | 'concepts' | 'code' | 'deepdive' | 'docs';

let selection: Selection = { kind: 'prereqMain' };
let activeTab: DetailTab = 'tutorial';
let activeFileName: string | null = null;
let activeConceptId: string | null = null;
let activeClusterPageId: string | null = null;
let pendingAnchor: string | null = null;

function findOs(num: number): LibOsModule | undefined {
  return DATA!.LIBRARY_OS_MODULES.find((m) => m.num === num);
}
function findBrowser(num: number): LibBrowserModule | undefined {
  return DATA!.LIBRARY_BROWSER_MODULES.find((m) => m.num === num);
}
function findCluster(id: string): LibCluster | undefined {
  return DATA!.LIBRARY_CLUSTERS.find((c) => c.id === id);
}
function findPrereqTopic(id: string): LibPrereqTopic | undefined {
  return DATA!.PREREQUISITE_TOPICS.find((p) => p.id === id);
}

/** Resolves an "unchanged" file's real content by walking back to the
 * module that actually introduced/last modified it, since the generated
 * data omits duplicate bytes for files carried forward unmodified. */
function resolveFileCode(f: LibFile): string {
  if (f.status !== 'unchanged') return f.code;
  const origin = findOs(f.originNum);
  const originFile = origin?.files.find((of) => of.name === f.name);
  return originFile && originFile.status !== 'unchanged' ? originFile.code : f.code;
}

export async function renderModuleLibrary(container: HTMLElement): Promise<void> {
  container.innerHTML = `<div class="lib-loading">Loading the full course library (~2 MB, one-time)&hellip;</div>`;
  if (!DATA) DATA = await import('./library.generated');

  container.innerHTML = `
    <div class="lib-layout">
      <div class="lib-nav" id="lib-nav"></div>
      <div class="lib-detail" id="lib-detail"></div>
    </div>
  `;
  renderNav(container);
  renderDetail(container);
}

function phaseGroups<T extends { phase: string }>(items: T[]): { phase: string; items: T[] }[] {
  const order: string[] = [];
  const map = new Map<string, T[]>();
  for (const it of items) {
    if (!map.has(it.phase)) { map.set(it.phase, []); order.push(it.phase); }
    map.get(it.phase)!.push(it);
  }
  return order.map((phase) => ({ phase, items: map.get(phase)! }));
}

function isActive(sel: Selection): boolean {
  return JSON.stringify(sel) === JSON.stringify(selection);
}

function goTo(sel: Selection, root: HTMLElement, tab: DetailTab = 'tutorial', anchor: string | null = null): void {
  selection = sel;
  activeTab = tab;
  activeFileName = null;
  activeConceptId = null;
  activeClusterPageId = null;
  pendingAnchor = anchor;
  renderNav(root);
  renderDetail(root);
}

function renderNav(root: HTMLElement): void {
  const nav = root.querySelector<HTMLElement>('#lib-nav')!;
  const d = DATA!;

  let html = '';

  html += `<details class="lib-group" open>
    <summary>Prerequisites</summary>
    <button class="lib-nav-item ${isActive({ kind: 'prereqMain' }) ? 'active' : ''}" data-sel='${tsSel({ kind: 'prereqMain' })}'>
      Hardware &amp; Assembly Primer <span class="lib-nav-hint">(linked from every module)</span>
    </button>
    <div class="lib-subgroup-label">Same topics, one page each:</div>
    ${d.PREREQUISITE_TOPICS.map(
      (p) => `<button class="lib-nav-item lib-nav-sub ${isActive({ kind: 'prereqTopic', id: p.id }) ? 'active' : ''}" data-sel='${tsSel({ kind: 'prereqTopic', id: p.id })}'>${esc(p.title)}</button>`
    ).join('')}
  </details>`;

  html += `<details class="lib-group" open>
    <summary>OS Kernel Track <span class="lib-count">(${d.LIBRARY_OS_MODULES.length})</span></summary>`;
  for (const { phase, items } of phaseGroups(d.LIBRARY_OS_MODULES)) {
    html += `<div class="lib-phase-label">${esc(phase)}</div>`;
    for (const m of items) {
      const sel: Selection = { kind: 'os', num: m.num };
      html += `<button class="lib-nav-item ${isActive(sel) ? 'active' : ''}" data-sel='${tsSel(sel)}'>
        <span class="lib-nav-num">${String(m.num).padStart(2, '0')}</span>${esc(m.title)}
        ${m.hasLive ? '<span class="lib-live-dot" title="Has a live demo above"></span>' : ''}
      </button>`;
    }
  }
  html += `</details>`;

  html += `<details class="lib-group">
    <summary>Browser Security Track <span class="lib-count">(${d.LIBRARY_BROWSER_MODULES.length})</span></summary>`;
  for (const { phase, items } of phaseGroups(d.LIBRARY_BROWSER_MODULES)) {
    html += `<div class="lib-phase-label">${esc(phase)}</div>`;
    for (const m of items) {
      const sel: Selection = { kind: 'browser', num: m.num };
      html += `<button class="lib-nav-item ${isActive(sel) ? 'active' : ''}" data-sel='${tsSel(sel)}'>
        <span class="lib-nav-num">B${String(m.num).padStart(2, '0')}</span>${esc(m.title)}
      </button>`;
    }
  }
  html += `</details>`;

  html += `<details class="lib-group">
    <summary>Deep-Dive Lessons <span class="lib-count">(${d.LIBRARY_CLUSTERS.length})</span></summary>
    <div class="lib-subgroup-label">Cross-cutting concepts spanning more than one module — history, hardware mechanism, and real-world usage in more depth than one module's code alone motivates.</div>
    ${d.LIBRARY_CLUSTERS.map((c) => {
      const sel: Selection = { kind: 'cluster', id: c.id };
      return `<button class="lib-nav-item ${isActive(sel) ? 'active' : ''}" data-sel='${tsSel(sel)}'>${esc(c.title)}</button>`;
    }).join('')}
  </details>`;

  nav.innerHTML = html;
  nav.querySelectorAll<HTMLButtonElement>('.lib-nav-item').forEach((btn) => {
    btn.addEventListener('click', () => {
      const sel = JSON.parse(btn.dataset.sel!) as Selection;
      goTo(sel, root);
    });
  });
}

function tsSel(sel: Selection): string {
  return escAttr(JSON.stringify(sel));
}

function docCard(d: { title: string; description: string; url: string }): string {
  return `<div class="doc-card">
    <span class="doc-card-icon">\u{1F4C4}</span>
    <div class="doc-card-body">
      <strong>${esc(d.title)}</strong> — ${esc(d.description)}<br>
      <a href="${d.url}" target="_blank" rel="noopener noreferrer">${d.url}</a>
    </div>
  </div>`;
}

type LinkTarget =
  | { kind: 'prereqMain'; anchor: string | null }
  | { kind: 'os'; num: number }
  | { kind: 'browser'; num: number }
  | { kind: 'concept'; id: string }
  | { kind: 'deepdive' };

/** Real tutorial.html files link to `../prerequisite.html[#sec-x]`, sibling
 * `../NN_module/tutorial.html` (one level up for OS modules, two for
 * browser modules), sibling `../BXX_module/tutorial.html`, `DECISIONS.md`,
 * and — inside module 01 only — same-directory `concept_*.html`/
 * `*_deepdive.html`. These only resolve inside the real course repo, not
 * this deployed SPA, so they're intercepted and routed to the matching
 * tab/module in this app instead of being followed for real and 404ing. */
function resolveInternalLink(hrefNoQuery: string): LinkTarget | null {
  const [pathPart, anchor] = hrefNoQuery.split('#');
  if (/prerequisite\.html$/.test(pathPart) || pathPart === '') {
    if (/prerequisite\.html$/.test(hrefNoQuery.split('#')[0])) return { kind: 'prereqMain', anchor: anchor ?? null };
  }
  if (/DECISIONS\.md$/.test(pathPart)) return { kind: 'deepdive' };
  const tutorialMatch = pathPart.match(/([^/]+)\/tutorial\.html$/);
  if (tutorialMatch) {
    const dirName = tutorialMatch[1];
    const os = DATA!.LIBRARY_OS_MODULES.find((m) => m.dir.split('/').pop() === dirName);
    if (os) return { kind: 'os', num: os.num };
    const br = DATA!.LIBRARY_BROWSER_MODULES.find((m) => m.dir.split('/').pop() === dirName);
    if (br) return { kind: 'browser', num: br.num };
    return null;
  }
  if (/^(concept_[a-z0-9_]+|[a-z_]+_deepdive)\.html$/.test(pathPart)) {
    return { kind: 'concept', id: pathPart.replace(/\.html$/, '') };
  }
  return null;
}

/** External links get target=_blank so they open a real new tab instead of
 * hijacking the iframe. Relative links get intercepted and routed to the
 * matching tab/module in this app. Anchors on the prerequisite page are
 * honored by scrolling the iframe to that heading after it loads. */
function wireContentFrame(iframe: HTMLIFrameElement, root: HTMLElement): void {
  iframe.addEventListener('load', () => {
    const doc = iframe.contentDocument;
    if (!doc) return;
    if (pendingAnchor) {
      const target = doc.getElementById(pendingAnchor);
      target?.scrollIntoView({ block: 'start' });
      pendingAnchor = null;
    }
    doc.querySelectorAll<HTMLAnchorElement>('a[href]').forEach((a) => {
      const href = a.getAttribute('href') || '';
      if (/^https?:\/\//.test(href)) {
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        return;
      }
      a.addEventListener('click', (e) => {
        e.preventDefault();
        const resolved = resolveInternalLink(href);
        if (!resolved) return;
        if (resolved.kind === 'prereqMain') goTo({ kind: 'prereqMain' }, root, 'tutorial', resolved.anchor);
        else if (resolved.kind === 'os') goTo({ kind: 'os', num: resolved.num }, root);
        else if (resolved.kind === 'browser') goTo({ kind: 'browser', num: resolved.num }, root);
        else if (resolved.kind === 'deepdive') { activeTab = 'deepdive'; renderDetail(root); }
        else if (resolved.kind === 'concept' && selection.kind === 'os') {
          activeTab = 'concepts';
          activeConceptId = resolved.id;
          renderDetail(root);
        }
      });
    });
  });
}

function frameHtml(doc: string): string {
  return `<iframe class="lib-content-frame" sandbox="allow-same-origin" srcdoc="${escAttr(buildThemedDoc(doc))}"></iframe>`;
}

function fileStatusBadge(f: LibFile): string {
  if (f.status === 'new') return `<span class="lib-file-badge new">new</span>`;
  if (f.status === 'modified') return `<span class="lib-file-badge modified">modified</span>`;
  return `<span class="lib-file-badge unchanged">since Module ${String(f.originNum).padStart(2, '0')}</span>`;
}

function renderCodeTab(root: HTMLElement, files: LibFile[]): void {
  const body = root.querySelector<HTMLElement>('#lib-tab-body')!;
  if (files.length === 0) {
    body.innerHTML = '<div class="desc">No source files found for this module.</div>';
    return;
  }
  if (!activeFileName || !files.some((f) => f.name === activeFileName)) activeFileName = files[0].name;
  const active = files.find((f) => f.name === activeFileName)!;
  const code = resolveFileCode(active);

  body.innerHTML = `
    <div class="lib-file-tabs">${files
      .map((f) => `<button class="lib-file-tab ${f.name === activeFileName ? 'active' : ''}" data-file="${esc(f.name)}">${esc(f.name)}</button>`)
      .join('')}</div>
    <div class="lib-code-toolbar">
      ${fileStatusBadge(active)}
      <button class="lib-copy-btn" id="lib-copy-btn">Copy file</button>
    </div>
    <pre class="lib-code"><code>${esc(code)}</code></pre>
  `;
  body.querySelectorAll<HTMLButtonElement>('.lib-file-tab').forEach((btn) => {
    btn.addEventListener('click', () => { activeFileName = btn.dataset.file!; renderCodeTab(root, files); });
  });
  const copyBtn = body.querySelector<HTMLButtonElement>('#lib-copy-btn')!;
  copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(code);
      copyBtn.textContent = 'Copied!';
    } catch {
      copyBtn.textContent = 'Select all + Ctrl/Cmd+C';
    }
    setTimeout(() => { copyBtn.textContent = 'Copy file'; }, 1600);
  });
}

function renderDeepDiveTab(root: HTMLElement, sections: { title: string; body: string }[]): void {
  const body = root.querySelector<HTMLElement>('#lib-tab-body')!;
  body.innerHTML = sections.length
    ? sections.map((s) => `<div class="lib-decision-card"><div class="lib-decision-title">${esc(s.title)}</div><div class="lib-decision-body">${mdLite(s.body)}</div></div>`).join('')
    : '<div class="desc">No DECISIONS.md found for this module.</div>';
}

function renderDocsTab(root: HTMLElement, docs: { title: string; description: string; url: string }[]): void {
  const body = root.querySelector<HTMLElement>('#lib-tab-body')!;
  body.innerHTML = docs.length ? docs.map(docCard).join('') : '<div class="desc">No doc links recorded for this phase.</div>';
}

function renderDetail(root: HTMLElement): void {
  const detail = root.querySelector<HTMLElement>('#lib-detail')!;
  const d = DATA!;

  if (selection.kind === 'prereqMain') {
    detail.innerHTML = `
      <div class="lib-eyebrow">Prerequisite</div>
      <h2>Hardware &amp; Assembly Primer</h2>
      <p class="desc">The single page every module's tutorial links back to for registers, memory, the stack, real mode, and toolchain setup.</p>
      <div id="lib-tab-body"></div>
    `;
    detail.querySelector<HTMLElement>('#lib-tab-body')!.innerHTML = frameHtml(d.PREREQUISITE_MAIN);
    wireContentFrame(detail.querySelector('iframe')!, root);
    return;
  }

  if (selection.kind === 'prereqTopic') {
    const p = findPrereqTopic(selection.id)!;
    detail.innerHTML = `
      <div class="lib-eyebrow">Prerequisite · Topic-by-Topic</div>
      <h2>${esc(p.title)}</h2>
      <div id="lib-tab-body"></div>
    `;
    detail.querySelector<HTMLElement>('#lib-tab-body')!.innerHTML = frameHtml(p.html);
    wireContentFrame(detail.querySelector('iframe')!, root);
    return;
  }

  if (selection.kind === 'cluster') {
    const c = findCluster(selection.id)!;
    if (!activeClusterPageId || !c.pages.some((p) => p.id === activeClusterPageId)) activeClusterPageId = c.pages[0]?.id ?? null;
    const relates = [
      ...c.relatesToOS.map((n) => `<a class="lib-dep-link" data-kind="os" data-num="${n}">Module ${String(n).padStart(2, '0')}</a>`),
      ...c.relatesToBrowser.map((n) => `<a class="lib-dep-link" data-kind="browser" data-num="${n}">Module B${String(n).padStart(2, '0')}</a>`),
    ].join(', ');
    detail.innerHTML = `
      <div class="lib-eyebrow">Deep-Dive Lesson</div>
      <h2>${esc(c.title)}</h2>
      ${relates ? `<div class="lib-depends">Relates to: ${relates}</div>` : ''}
      <div class="lib-file-tabs">${c.pages.map((p) => `<button class="lib-file-tab ${p.id === activeClusterPageId ? 'active' : ''}" data-page="${esc(p.id)}">${esc(p.title.length > 34 ? p.id : p.title)}</button>`).join('')}</div>
      <div id="lib-tab-body"></div>
    `;
    detail.querySelectorAll<HTMLAnchorElement>('.lib-dep-link').forEach((a) => {
      a.addEventListener('click', () => goTo(a.dataset.kind === 'os' ? { kind: 'os', num: Number(a.dataset.num) } : { kind: 'browser', num: Number(a.dataset.num) }, root));
    });
    const page = c.pages.find((p) => p.id === activeClusterPageId);
    detail.querySelector<HTMLElement>('#lib-tab-body')!.innerHTML = page ? frameHtml(page.html) : '<div class="desc">No pages in this cluster.</div>';
    if (page) wireContentFrame(detail.querySelector('iframe')!, root);
    detail.querySelectorAll<HTMLButtonElement>('.lib-file-tab').forEach((btn) => {
      btn.addEventListener('click', () => { activeClusterPageId = btn.dataset.page!; renderDetail(root); });
    });
    return;
  }

  if (selection.kind === 'browser') {
    const m = findBrowser(selection.num)!;
    const tabs: { id: DetailTab; label: string }[] = [
      { id: 'tutorial', label: 'Tutorial' },
      { id: 'code', label: `Real Code (${m.files.length})` },
      { id: 'deepdive', label: `Deep Dive (${m.deepDive.length})` },
      { id: 'docs', label: 'Docs' },
    ];
    const osLinks = m.osConnection.map((n) => `<a class="lib-dep-link" data-kind="os" data-num="${n}">Module ${String(n).padStart(2, '0')}</a>`).join(', ');
    const brLinks = m.dependsBrowser.map((n) => `<a class="lib-dep-link" data-kind="browser" data-num="${n}">Module B${String(n).padStart(2, '0')}</a>`).join(', ');
    detail.innerHTML = `
      <div class="lib-eyebrow">Browser Module B${String(m.num).padStart(2, '0')} · ${esc(m.phase)}</div>
      <h2>${esc(m.title)}</h2>
      <p class="desc">${esc(m.proves)}</p>
      ${osLinks ? `<div class="lib-depends">Kernel mechanism reused: ${osLinks}</div>` : ''}
      ${brLinks ? `<div class="lib-depends">Depends on: ${brLinks}</div>` : ''}
      <div class="tabs lib-tabs">${tabs.map((t) => `<button class="tab-btn ${t.id === activeTab ? 'active' : ''}" data-libtab="${t.id}">${t.label}</button>`).join('')}</div>
      <div id="lib-tab-body"></div>
    `;
    detail.querySelectorAll<HTMLAnchorElement>('.lib-dep-link').forEach((a) => {
      a.addEventListener('click', () => goTo(a.dataset.kind === 'os' ? { kind: 'os', num: Number(a.dataset.num) } : { kind: 'browser', num: Number(a.dataset.num) }, root));
    });
    detail.querySelectorAll<HTMLButtonElement>('[data-libtab]').forEach((btn) => {
      btn.addEventListener('click', () => { activeTab = btn.dataset.libtab as DetailTab; renderDetail(root); });
    });
    if (activeTab === 'tutorial') {
      detail.querySelector<HTMLElement>('#lib-tab-body')!.innerHTML = frameHtml(m.tutorial);
      wireContentFrame(detail.querySelector('iframe')!, root);
    } else if (activeTab === 'code') renderCodeTab(root, m.files);
    else if (activeTab === 'deepdive') renderDeepDiveTab(root, m.deepDive);
    else renderDocsTab(root, m.docs);
    return;
  }

  // selection.kind === 'os'
  const m = findOs(selection.num)!;
  const tabs: { id: DetailTab; label: string }[] = [
    { id: 'tutorial', label: 'Tutorial' },
    ...(m.concepts.length ? [{ id: 'concepts' as DetailTab, label: `Concepts (${m.concepts.length})` }] : []),
    { id: 'code', label: `Real Code (${m.files.length})` },
    { id: 'deepdive', label: `Deep Dive (${m.deepDive.length})` },
    { id: 'docs', label: 'Docs' },
  ];
  detail.innerHTML = `
    <div class="lib-eyebrow">Module ${String(m.num).padStart(2, '0')} · ${esc(m.phase)}${m.hasLive ? ' · <span class="lib-has-live">has a live demo above</span>' : ''}</div>
    <h2>${esc(m.title)}</h2>
    <p class="desc">${esc(m.proves)}</p>
    ${m.num > 1 ? `<div class="lib-depends">Builds on: <a class="lib-dep-link" data-kind="os" data-num="${m.num - 1}">Module ${String(m.num - 1).padStart(2, '0')}</a> (every OS module carries the full kernel forward)</div>` : ''}
    <div class="tabs lib-tabs">${tabs.map((t) => `<button class="tab-btn ${t.id === activeTab ? 'active' : ''}" data-libtab="${t.id}">${t.label}</button>`).join('')}</div>
    <div id="lib-tab-body"></div>
  `;
  detail.querySelectorAll<HTMLAnchorElement>('.lib-dep-link').forEach((a) => {
    a.addEventListener('click', () => goTo({ kind: 'os', num: Number(a.dataset.num) }, root));
  });
  detail.querySelectorAll<HTMLButtonElement>('[data-libtab]').forEach((btn) => {
    btn.addEventListener('click', () => { activeTab = btn.dataset.libtab as DetailTab; renderDetail(root); });
  });

  if (activeTab === 'tutorial') {
    detail.querySelector<HTMLElement>('#lib-tab-body')!.innerHTML = frameHtml(m.tutorial);
    wireContentFrame(detail.querySelector('iframe')!, root);
  } else if (activeTab === 'concepts') {
    if (!activeConceptId || !m.concepts.some((c) => c.id === activeConceptId)) activeConceptId = m.concepts[0]?.id ?? null;
    const body = detail.querySelector<HTMLElement>('#lib-tab-body')!;
    body.innerHTML = `
      <div class="lib-file-tabs">${m.concepts.map((c) => `<button class="lib-file-tab ${c.id === activeConceptId ? 'active' : ''}" data-concept="${esc(c.id)}">${esc(c.title)}</button>`).join('')}</div>
      <div id="lib-concept-frame"></div>
    `;
    const concept = m.concepts.find((c) => c.id === activeConceptId);
    body.querySelector<HTMLElement>('#lib-concept-frame')!.innerHTML = concept ? frameHtml(concept.html) : '';
    if (concept) wireContentFrame(body.querySelector('iframe')!, root);
    body.querySelectorAll<HTMLButtonElement>('.lib-file-tab').forEach((btn) => {
      btn.addEventListener('click', () => { activeConceptId = btn.dataset.concept!; renderDetail(root); });
    });
  } else if (activeTab === 'code') renderCodeTab(root, m.files);
  else if (activeTab === 'deepdive') renderDeepDiveTab(root, m.deepDive);
  else renderDocsTab(root, m.docs);
}
